// th16_s3_mb2 — TH16 v1.00a Stage 3 midboss, card 2 (春符「サプライズスプリング」)
// Source: st03mbs.ecl.txt MBossCard1:164-313 (entry) and MBossCard1_at:215-313 (dependency).
// Source t=0 is MBossCard1:173 timerReset; entry state inherited from MBoss: position (0,128),
// hurtbox 48x48 -> r24, hitbox 40x40 -> r20. Source limit 1320 (MBossCard1:192).
// Shell: 120-frame opening buffer, then source t=0; TIME_LIMIT = 120 + 1320 + 4.

const TIME_LIMIT: int = 1444;
const OPENING_BUFFER: int = 120;

// ---- moveRand(60, 0, 1.0) under moveLimit(0, 128, 280, 64) ----
// x limit [-140,140], y limit [96,160]; direction inner region x +/- 70, y 112..144.
// Owner slot ownership: int0 = next movement step, fx0/fx1 = logical unit vector.
sub mr_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mr_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mr_arm_next_step();
}

sub mr_move_rand() {
    // Source 412: signed unit random * pi, then +pi branches; values below stay unwrapped BAM.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad -> 522 BAM around 16384.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mr_begin_angle(a as angle);
}

// ---- source MBossCard1 main task ----
async sub mboss_card1() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    // MBossCard1:197 movePosTime(60, 4, 0, 144): ABS move from (0,128) to (0,144).
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    wait(30);                               // MBossCard1:201 label +90
    spawn mboss_card1_at();                 // MBossCard1:204 @MBossCard1_at() async
    for cycle in 0..3 {
        wait(300);                          // MBossCard1_1040 wait(300)
        mr_move_rand();                     // MBossCard1:208 moveRand(60, 0, 1.0)
        for k in 0..60 { wait(1); mr_arm_next_step(); }
    }
    wait(150);                              // hold to source t=1320 (timeout boundary)
}

// ---- source MBossCard1_at: four fixed-direction fans, one wave per slot every 3 frames ----
async sub mboss_card1_at() {
    var rank: int = global(GVAR_RANK);
    // Sprites: etSprite type 8 (TH16_RICE) colors 4/6/10/13.
    // etDist net of the retained birth retreat: dist - 4*speed (ANIM a=1).
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 4);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 8, 1);
    sh_speed(0, 1.0fx, 0fx);
    sh_dist(0, 76fx);                       // 80 - 4*1.0
    sh_reset(1);
    sh_sprite(1, TH16_RICE, 6);
    sh_aim(1, 0);
    sh_ring(1, 0);
    sh_count(1, 8, 1);
    sh_speed(1, 1.5fx, 0fx);
    sh_dist(1, 58fx);                       // 64 - 4*1.5
    sh_reset(2);
    sh_sprite(2, TH16_RICE, 10);
    sh_aim(2, 0);
    sh_ring(2, 0);
    sh_count(2, 8, 1);
    sh_speed(2, 2.0fx, 0fx);
    sh_dist(2, 8fx);                        // 16 - 4*2.0
    sh_reset(3);
    sh_sprite(3, TH16_RICE, 13);
    sh_aim(3, 0);
    sh_ring(3, 0);
    if rank == RANK_LUNATIC { sh_count(3, 12, 1); } else { sh_count(3, 8, 1); }
    sh_speed(3, 2.5fx, 0fx);
    sh_dist(3, 38fx);                       // 48 - 4*2.5

    var a0: angle = 180deg;
    var a1: angle = 0deg;
    var a2: angle = -90deg;
    var a3: angle = -90deg;
    var left: int = 8000;                   // source $E = 8000
    loop {
        sh_angle(0, a0, 11deg); sh_fire(0); a0 = a0 - 10deg;
        wait(3);
        sh_angle(1, a1, 9deg); sh_fire(1); a1 = a1 + 25deg;
        wait(3);
        sh_angle(2, a2, -10.4deg); sh_fire(2); a2 = a2 - 20deg;
        wait(3);
        if rank == RANK_LUNATIC {
            sh_angle(3, a3, -7deg); sh_fire(3); a3 = a3 + 30deg;
            wait(3);
        }
        left = left - 1;
        if left <= 0 { return; }
    }
}

// ---- training shell (validation.md) ----
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 0, mboss_card1);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

